-- compare_xq.tsv: for each literal, how many rows of tx `xq <op> <literal>` keeps, the
-- sum of their id, and how many rows DuckDB cannot decide (the comparison raises a
-- conversion error: TRY gives NULL for a row whose xq is not NULL), for each of the six
-- comparison operators. The literal is the SQL text the test runs too (a folded bound is
-- written as the arithmetic), so the file holds DuckDB's reading of it. NULL rows are in
-- neither the kept rows nor their complement. Column xq is DECIMAL(38, 2) and holds +-10^20: widening it to a scale of 18 or more overflows DECIMAL(38).
COPY (
SELECT * FROM (
  SELECT 0 AS n, 'xq' AS col, '0.06' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xq < 0.06)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xq < 0.06)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xq < 0.06) IS NULL AND xq IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xq <= 0.06)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xq <= 0.06)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xq <= 0.06) IS NULL AND xq IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xq > 0.06)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xq > 0.06)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xq > 0.06) IS NULL AND xq IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xq >= 0.06)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xq >= 0.06)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xq >= 0.06) IS NULL AND xq IS NOT NULL) AS ge_e,
    (SELECT count(*) FROM tx WHERE TRY(xq = 0.06)) AS eq_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xq = 0.06)) AS eq_s, (SELECT count(*) FROM tx WHERE TRY(xq = 0.06) IS NULL AND xq IS NOT NULL) AS eq_e,
    (SELECT count(*) FROM tx WHERE TRY(xq <> 0.06)) AS ne_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xq <> 0.06)) AS ne_s, (SELECT count(*) FROM tx WHERE TRY(xq <> 0.06) IS NULL AND xq IS NOT NULL) AS ne_e
  UNION ALL
  SELECT 1 AS n, 'xq' AS col, '0.065' AS lit,
    (SELECT count(*) FROM tx WHERE TRY(xq < 0.065)) AS lt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xq < 0.065)) AS lt_s, (SELECT count(*) FROM tx WHERE TRY(xq < 0.065) IS NULL AND xq IS NOT NULL) AS lt_e,
    (SELECT count(*) FROM tx WHERE TRY(xq <= 0.065)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xq <= 0.065)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xq <= 0.065) IS NULL AND xq IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xq > 0.065)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xq > 0.065)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xq > 0.065) IS NULL AND xq IS NOT NULL) AS gt_e,
    (SELECT count(*) FROM tx WHERE TRY(xq >= 0.065)) AS ge_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xq >= 0.065)) AS ge_s, (SELECT count(*) FROM tx WHERE TRY(xq >= 0.065) IS NULL AND xq IS NOT NULL) AS ge_e,
