    (SELECT count(*) FROM tx WHERE TRY(xq <= 0.00000000000000001)) AS le_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xq <= 0.00000000000000001)) AS le_s, (SELECT count(*) FROM tx WHERE TRY(xq <= 0.00000000000000001) IS NULL AND xq IS NOT NULL) AS le_e,
    (SELECT count(*) FROM tx WHERE TRY(xq > 0.00000000000000001)) AS gt_n, (SELECT CAST(coalesce(sum(id), 0) AS BIGINT) FROM tx WHERE TRY(xq > 0.00000000000000001)) AS gt_s, (SELECT count(*) FROM tx WHERE TRY(xq > 0.00000000000000001) IS NULL AND xq IS NOT NULL) AS gt_e,
